:root {
  color-scheme: dark;
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  font-size: 16px;
  background: #20263a;
  color: #f5f3eb;
  --ink: #20263a;
  --panel: #2d354d;
  --field: #242b40;
  --mint: #9af0cf;
  --cream: #f5f3eb;
  --muted: #b5bdd0;
}

* { box-sizing: border-box; }
body {
  min-height: 100vh;
  margin: 0;
  padding: 32px 16px;
  display: grid;
  place-items: center;
  background-color: var(--ink);
  background-image: radial-gradient(#39415b 1px, transparent 1px);
  background-size: 18px 18px;
}
.card {
  width: min(100%, 510px);
  padding: 34px;
  border: 2px solid #69738d;
  border-radius: 8px;
  background: var(--panel);
  box-shadow: 8px 8px 0 #151a29;
}
.header { text-align: center; margin-bottom: 28px; }
.pixel-mark {
  display: grid;
  place-items: center;
  width: 48px;
  height: 48px;
  margin: 0 auto 14px;
  color: var(--ink);
  background: var(--mint);
  border: 4px solid var(--cream);
  box-shadow: 4px 4px 0 var(--ink);
  font-size: 25px;
}
.eyebrow { margin: 0 0 7px; color: var(--mint); font-size: 0.8rem; font-weight: 750; letter-spacing: 0.14em; }
h1 { margin: 0; font-size: clamp(1.8rem, 8vw, 2.5rem); line-height: 1.15; letter-spacing: -0.04em; }
.intro { margin: 10px 0 0; color: var(--muted); }
form { display: grid; gap: 10px; }
label { font-weight: 700; }
.hint { color: var(--muted); font-weight: 400; }
textarea, input {
  width: 100%;
  padding: 13px 14px;
  border: 2px solid #68738e;
  border-radius: 5px;
  background: var(--field);
  color: var(--cream);
  font: inherit;
  line-height: 1.5;
}
textarea { resize: vertical; min-height: 88px; }
textarea::placeholder { color: #a1abc2; }
input { max-width: 130px; }
textarea:focus-visible, input:focus-visible, button:focus-visible { outline: 3px solid var(--mint); outline-offset: 3px; }
.actions { display: flex; gap: 12px; margin: 8px 0 12px; }
button {
  min-height: 48px;
  padding: 10px 16px;
  border: 2px solid var(--mint);
  border-radius: 5px;
  background: var(--mint);
  color: var(--ink);
  font: inherit;
  font-weight: 750;
  cursor: pointer;
  transition: transform 100ms ease, filter 100ms ease, box-shadow 100ms ease;
  box-shadow: 3px 3px 0 var(--ink);
}
.actions button { flex: 1; }
button:hover { filter: brightness(1.08); }
button:active { transform: translate(2px, 2px); box-shadow: 1px 1px 0 var(--ink); }
button.secondary { background: transparent; color: var(--mint); }
.result-heading { display: flex; align-items: center; justify-content: space-between; }
.copy-button { min-height: 36px; padding: 5px 12px; font-size: 0.9rem; }
.status { min-height: 1.25em; margin: 0; color: var(--mint); font-size: 0.9rem; }
footer { margin-top: 22px; padding-top: 16px; border-top: 1px solid #56617b; color: var(--muted); text-align: center; font-size: 0.9rem; }
@media (max-width: 420px) {
  .card { padding: 24px 18px; }
  body { padding: 18px 12px; }
}

const messageField = document.getElementById('message');
const shiftField = document.getElementById('shift');
const resultField = document.getElementById('result');
const status = document.getElementById('status');

function transform(direction) {
  const shift = Number(shiftField.value);
  if (!Number.isInteger(shift) || shift < 1 || shift > 25) {
    shiftField.setCustomValidity('Enter a whole number from 1 to 25.');
    shiftField.reportValidity();
    shiftField.setCustomValidity('');
    return;
  }

  const offset = direction * shift;
  resultField.value = Array.from(messageField.value, (character) => {
    const code = character.charCodeAt(0);
    const base = code >= 65 && code <= 90 ? 65 : code >= 97 && code <= 122 ? 97 : -1;
    return base < 0 ? character : String.fromCharCode(((code - base + offset + 26) % 26) + base);
  }).join('');
  status.textContent = direction > 0 ? 'Message encoded.' : 'Message decoded.';
}

document.getElementById('encode').addEventListener('click', () => transform(1));
document.getElementById('decode').addEventListener('click', () => transform(-1));
document.getElementById('copy').addEventListener('click', async () => {
  if (!resultField.value) {
    status.textContent = 'There is no result to copy yet.';
    return;
  }
  try {
    await navigator.clipboard.writeText(resultField.value);
    status.textContent = 'Result copied.';
  } catch {
    resultField.focus();
    resultField.select();
    status.textContent = 'Select the result and copy it with your keyboard.';
  }
});
